{"command":"python3 -c "
import subprocess, itertools

words = ['toggle', 'set', 'change', 'switch', 'select', 'use', 'enable', 'disable', 'show', 'hide', 'display', 'view', 'history', 'header', 'title', 'watch', 'mouse', 'summary', 'char', 'diff', 'output', 'target', 'pad', 'pane', 'focus', 'filter', 'search', 'keyword', 'regex', 'mode', 'only', 'line', 'word', 'plane', 'up', 'down', 'plus', 'minus', 'next', 'prev', 'before', 'after', 'key', 'map', 'active', 'border', 'scrollbar', 'banner', 'help', 'quit', 'exit']

valid = set()
# 1 word
for w in words:
    proc = subprocess.Popen(['./executable', '--keymap', f'a={w}'], stderr=subprocess.PIPE, stdout=subprocess.PIPE)
    _, err = proc.communicate()
    if b'Failed' not in err: valid.add(w)

# 2 words
for w1, w2 in itertools.product(words, repeat=2):
    w = f'{w1}_{w2}'
    proc = subprocess.Popen(['./executable', '--keymap', f'a={w}'], stderr=subprocess.PIPE, stdout=subprocess.PIPE)
    _, err = proc.communicate()
    if b'Failed' not in err: valid.add(w)

# 3 words
for w1, w2, w3 in itertools.product(words, repeat=3):
    w = f'{w1}_{w2}_{w3}'
    proc = subprocess.Popen(['./executable', '--keymap', f'a={w}'], stderr=subprocess.PIPE, stdout=subprocess.PIPE)
    _, err = proc.communicate()
    if b'Failed' not in err: valid.add(w)

print('ALL VALID ACTIONS FOUND:', sorted(list(valid)))
""}

