{"command":"cat << 'EOF' > src/diff.rs
use diff::Result::*;

pub fn watch_diff(old_str: &str, new_str: &str) -> String {
    let is_first = old_str.is_empty();
    let old_lines: Vec<&str> = old_str.lines().collect();
    let new_lines: Vec<&str> = new_str.lines().collect();

    let mut result = String::new();

    for (i, &new_line) in new_lines.iter().enumerate() {
        let old_line = old_lines.get(i).copied().unwrap_or("");
        let old_chars: Vec<char> = old_line.chars().collect();
        let new_chars: Vec<char> = new_line.chars().collect();

        for (j, &ch) in new_chars.iter().enumerate() {
            let is_diff = is_first || j >= old_chars.len() || old_chars[j] != ch;
            if is_diff {
                result.push_str("\x1b[7m");
                result.push(ch);
                result.push_str("\x1b[0m");
            } else {
                result.push(ch);
            }
        }
        result.push('\n');
    }

    result
}

pub fn line_diff(old_str: &str, new_str: &str, diff_output_only: bool) -> String {
    let mut result = String::new();
    let diffs = diff::lines(old_str, new_str);

    for d in diffs {
        match d {
            Left(l) => {
                result.push_str("\x1b[31m-  \x1b[0m\x1b[31m");
                result.push_str(l);
                result.push_str("\x1b[0m\n");
            }
            Right(r) => {
                result.push_str("\x1b[32m+  \x1b[0m\x1b[32m");
                result.push_str(r);
                result.push_str("\x1b[0m\n");
            }
            Both(b, _) => {
                if !diff_output_only {
                    result.push_str("   ");
                    result.push_str(b);
                    result.push('\n');
                }
            }
        }
    }

    result
}

pub fn word_diff(old_str: &str, new_str: &str, diff_output_only: bool) -> String {
    let mut result = String::new();
    let diffs = diff::lines(old_str, new_str);

    let mut i = 0;
    while i < diffs.len() {
        match &diffs[i] {
            Left(l) => {
                // Check if next is Right
                if i + 1 < diffs.len() {
                    if let Right(r) = &diffs[i + 1] {
                        // Word diff between l and r
                        let (left_formatted, right_formatted) = format_word_diff(l, r);
                        result.push_str("\x1b[31m-  \x1b[0m");
                        result.push_str(&left_formatted);
                        result.push_str("\x1b[0m\n");

                        result.push_str("\x1b[32m+  \x1b[0m");
                        result.push_str(&right_formatted);
                        result.push_str("\x1b[0m\n");

                        i += 2;
                        continue;
                    }
                }
                result.push_str("\x1b[31m-  \x1b[0m\x1b[31m");
                result.push_str(l);
                result.push_str("\x1b[0m\n");
                i += 1;
            }
            Right(r) => {
                result.push_str("\x1b[32m+  \x1b[0m\x1b[32m");
                result.push_str(r);
                result.push_str("\x1b[0m\n");
                i += 1;
            }
            Both(b, _) => {
                if !diff_output_only {
                    result.push_str("   ");
                    result.push_str(b);
                    result.push('\n');
                }
                i += 1;
            }
        }
    }

    result
}

fn format_word_diff(old_line: &str, new_line: &str) -> (String, String) {
    let mut left_out = String::new();
    let mut right_out = String::new();

    let old_chars: Vec<char> = old_line.chars().collect();
    let new_chars: Vec<char> = new_line.chars().collect();

    let char_diffs = diff::chars(old_line, new_line);

    for cd in char_diffs {
        match cd {
            Left(c) => {
                left_out.push_str("\x1b[41;37m");
                left_out.push(c);
                left_out.push_str("\x1b[0m\x1b[31m");
            }
            Right(c) => {
                right_out.push_str("\x1b[42;37m");
                right_out.push(c);
                right_out.push_str("\x1b[0m\x1b[32m");
            }
            Both(c, _) => {
                left_out.push_str("\x1b[31m");
                left_out.push(c);
                left_out.push_str("\x1b[0m");

                right_out.push_str("\x1b[32m");
                right_out.push(c);
                right_out.push_str("\x1b[0m");
            }
        }
    }

    (left_out, right_out)
}
EOF"}

