            &self.command,
            self.exec,
            &self.shell,
            self.output_mode,
        );
        self.add_record(record.clone());
        record
    }

    pub fn add_record(&mut self, record: HistoryRecord) {
        let prev_record = self.history.last().cloned().unwrap_or_default();
        let changed = prev_record.output != record.output
            || prev_record.status != record.status
            || prev_record.stdout != record.stdout
            || prev_record.stderr != record.stderr;

        if changed {
            if self.beep {
                print!("\x07");
                let _ = std::io::stdout().flush();
            }

            if let Some(after_cmd) = &self.aftercommand {
                let data = serde_json::json!({
