                let after_cmd_clone = after_cmd.clone();
                std::thread::spawn(move || {
                    let mut cmd = std::process::Command::new("sh");
                    cmd.arg("-c").arg(&after_cmd_clone);
                    cmd.env("HWATCH_DATA", data_str);
                    let _ = cmd.output();
                });
            }

            if let Some(logfile) = &self.logfile {
                if let Ok(mut file) = std::fs::OpenOptions::new()
                    .create(true)
                    .append(true)
                    .open(logfile)
                {
                    if let Ok(json_line) = serde_json::to_string(&record) {
                        let _ = writeln!(file, "{}", json_line);
                    }
                }
            }
        }

        self.history.push(record);
        if self.limit > 0 && self.history.len() > self.limit {
            self.history.remove(0);
        }
        self.selected_index = self.history.len().saturating_sub(1);
    }
}

pub fn run_command(
    command: &[String],
    exec_flag: bool,
    shell_cmd: &str,
    output_mode: OutputMode,
) -> HistoryRecord {
    let cmd_str = command.join(" ");
    let timestamp = chrono::Local::now().format("%Y-%m-%d %H:%M:%S%.3f").to_string();

    let output_result = if exec_flag {
        if command.is_empty() {
            None
        } else {
            std::process::Command::new(&command[0])
                .args(&command[1..])
                .output()
                .ok()
        }
    } else {
        if shell_cmd.contains("{COMMAND}") {
            let full_shell = shell_cmd.replace("{COMMAND}", &cmd_str);
            let parts = shlex::split(&full_shell).unwrap_or_else(|| vec!["sh".into(), "-c".into(), full_shell.clone()]);
            if parts.is_empty() {
                None
            } else {
                std::process::Command::new(&parts[0])
                    .args(&parts[1..])
                    .output()
                    .ok()
            }
        } else {
            let parts = shlex::split(shell_cmd).unwrap_or_else(|| vec!["sh".into(), "-c".into()]);
            if parts.is_empty() {
                None
            } else {
                let mut cmd = std::process::Command::new(&parts[0]);
                if parts.len() > 1 {
                    cmd.args(&parts[1..]);
                }
                cmd.arg(&cmd_str);
                cmd.output().ok()
            }
        }
    };

    let (status, stdout_str, stderr_str) = match output_result {
        Some(out) => {
            let status = out.status.success();
            let stdout_str = String::from_utf8_lossy(&out.stdout).to_string();
            let stderr_str = String::from_utf8_lossy(&out.stderr).to_string();
            (status, stdout_str, stderr_str)
        }
        None => (false, String::new(), String::new()),
    };

    let selected_output = match output_mode {
        OutputMode::Stdout => stdout_str.clone(),
        OutputMode::Stderr => stderr_str.clone(),
        OutputMode::Output => format!("{}{}", stdout_str, stderr_str),
    };

    HistoryRecord {
        timestamp,
        command: cmd_str,
        status,
        output: selected_output,
        stdout: stdout_str,
        stderr: stderr_str,
    }
}
