use crate::app::{App, DiffMode};
use crate::diff::{line_diff, watch_diff, word_diff};
use std::io::Write;
use std::thread;
use std::time::Duration;

pub fn run_batch_mode(app: &mut App) {
    let mut prev_output = String::new();

    loop {
        let record = app.run_once();
        let timestamp = &record.timestamp;

        // Print header
        print!(
            "\x1b[38;5;240m=====[{}]=========================\x1b[0m\n",
            timestamp
        );

        let formatted = format_output(
            &prev_output,
            &record.output,
            app.diff_mode,
            app.diff_output_only,
            app.line_number,
            app.reverse,
            app.tab_size,
        );

        print!("{}", formatted);
        if !formatted.ends_with('\n') {
            println!();
        }
        println!();
        let _ = std::io::stdout().flush();

        prev_output = record.output;

        let interval = if app.interval < 0.001 {
            0.001
        } else {
            app.interval
        };
        thread::sleep(Duration::from_secs_f64(interval));
    }
}

pub fn format_output(
    old_str: &str,
    new_str: &str,
    diff_mode: DiffMode,
    diff_output_only: bool,
    line_number: bool,
    reverse: bool,
    tab_size: usize,
) -> String {
    let tab_spaces = " ".repeat(tab_size);
    let mut text = match diff_mode {
        DiffMode::None => new_str.replace('\t', &tab_spaces),
        DiffMode::Watch => watch_diff(old_str, new_str).replace('\t', &tab_spaces),
        DiffMode::Line => line_diff(old_str, new_str, diff_output_only).replace('\t', &tab_spaces),
        DiffMode::Word => word_diff(old_str, new_str, diff_output_only).replace('\t', &tab_spaces),
    };

    if line_number {
        let lines: Vec<&str> = text.lines().collect();
        let width = lines.len().to_string().len();
        let mut numbered = String::new();
        for (idx, line) in lines.iter().enumerate() {
            numbered.push_str(&format!("{:width$} | {}\n", idx + 1, line, width = width));
        }
        text = numbered;
    }

    if reverse {
        let mut lines: Vec<&str> = text.lines().collect();
        lines.reverse();
        text = lines.join("\n");
        if !text.is_empty() {
            text.push('\n');
        }
    }

    text
}
EOF"}

