                Style::default().add_modifier(Modifier::BOLD),
            ),
            Span::raw("   "),
            if !app.no_help_banner {
                Span::raw("Display help with h key!")
            } else {
                Span::raw("")
            },
            Span::raw(" "),
            Span::raw(
                app.history
                    .last()
                    .map(|r| r.timestamp.as_str())
                    .unwrap_or(""),
            ),
        ]);

        let diff_str = match app.diff_mode {
            DiffMode::None => "[None      ]",
            DiffMode::Watch => "[Watch     ]",
            DiffMode::Line => "[Line      ]",
            DiffMode::Word => "[Word      ]",
        };

        let output_str = match app.output_mode {
            OutputMode::Output => "[Output]",
            OutputMode::Stdout => "[Stdout]",
            OutputMode::Stderr => "[Stderr]",
        };

        let num_badge = if app.line_number {
            Span::styled("[Number]", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))
        } else {
            Span::raw("[Number]")
        };

        let color_badge = if app.color {
            Span::styled("[Color]", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))
        } else {
            Span::raw("[Color]")
        };

        let rev_badge = if app.reverse {
            Span::styled("[Reverse]", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))
        } else {
            Span::raw("[Reverse]")
        };

        let out_badge = Span::styled(output_str, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD));
        let hist_badge = Span::raw("[History]");
        let diff_badge = Span::styled(diff_str, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD));

        let header_line2 = if let Some(fm) = app.filter_mode {
            let prompt = match fm {
                crate::app::FilterMode::Keyword => "/",
                crate::app::FilterMode::Regex => "*",
            };
            Line::from(vec![
                Span::styled(format!("{}{}", prompt, app.filter_query), Style::default().fg(Color::Cyan)),
                Span::raw("   "),
                num_badge, Span::raw(" "),
                color_badge, Span::raw(" "),
                rev_badge, Span::raw(" "),
                out_badge, Span::raw(" "),
                hist_badge, Span::raw(" "),
                diff_badge,
            ])
        } else if !app.filter_query.is_empty() {
            Line::from(vec![
                Span::styled(format!("/{}", app.filter_query), Style::default().fg(Color::Cyan)),
                Span::raw("   "),
                num_badge, Span::raw(" "),
                color_badge, Span::raw(" "),
                rev_badge, Span::raw(" "),
                out_badge, Span::raw(" "),
                hist_badge, Span::raw(" "),
                diff_badge,
            ])
        } else {
            Line::from(vec![
                Span::raw("                     "),
                num_badge, Span::raw(" "),
                color_badge, Span::raw(" "),
                rev_badge, Span::raw(" "),
                out_badge, Span::raw(" "),
                hist_badge, Span::raw(" "),
                diff_badge,
            ])
        };

        let header_paragraph = Paragraph::new(vec![header_line1, header_line2]);
        f.render_widget(header_paragraph, chunks[0]);
    }

    let main_chunk = if app.no_title { chunks[0] } else { chunks[1] };

    // Split into Watch Pane and History Pane
    let main_panes = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Min(30), Constraint::Length(28)])
        .split(main_chunk);

    // Watch Pane Content
    let curr_record = if !app.history.is_empty() {
        let idx = app.selected_index.min(app.history.len() - 1);
        &app.history[idx]
    } else {
        &crate::app::HistoryRecord::default()
    };

    let prev_record = if app.selected_index > 0 && app.selected_index < app.history.len() {
        &app.history[app.selected_index - 1]
    } else {
        &crate::app::HistoryRecord::default()
    };

    let output_text = format_output(
        &prev_record.output,
        &curr_record.output,
        app.diff_mode,
        app.diff_output_only,
        app.line_number,
        app.reverse,
        app.tab_size,
    );

    let watch_block = if app.border {
        Block::default().borders(Borders::ALL)
    } else {
        Block::default()
    };

    let watch_paragraph = Paragraph::new(output_text)
        .block(watch_block)
        .scroll((app.scroll_offset as u16, 0));

    f.render_widget(watch_paragraph, main_panes[0]);

    // Draw Scrollbar if requested
    if app.with_scrollbar {
        let scrollbar = Scrollbar::new(ScrollbarOrientation::VerticalRight);
        let mut scrollbar_state = ScrollbarState::new(100).position(app.scroll_offset);
        f.render_stateful_widget(scrollbar, main_panes[0], &mut scrollbar_state);
    }

    // History Pane Content
    let mut history_items = Vec::new();
    for (i, rec) in app.history.iter().enumerate() {
        let is_latest = i == app.history.len() - 1;
        let prefix = if i == app.selected_index {
            ">> "
        } else {
            "   "
        };
        let label = if is_latest {
            format!("{}latest\n  {}", prefix, rec.timestamp)
        } else {
            format!("{}{}", prefix, rec.timestamp)
        };
        history_items.push(Line::from(label));
    }

    let history_block = if app.border {
        Block::default().borders(Borders::LEFT)
    } else {
        Block::default()
    };

    let history_paragraph = Paragraph::new(history_items).block(history_block);
    f.render_widget(history_paragraph, main_panes[1]);

    // Help Overlay
    if app.show_help {
        let area = centered_rect(65, 70, size);
        f.render_widget(Clear, area);

        let help_text = vec![
            Line::from(" - [up] key : Move up"),
            Line::from(" - [down] key : Move down"),
            Line::from(" - [pageup] key : Move page up"),
            Line::from(" - [pagedown] key : Move page down"),
            Line::from(" - [home] key : Move top"),
            Line::from(" - [end] key : Move end"),
            Line::from(" - [tab] key : Toggle focus window"),
            Line::from(" - [left] key : Focus watch pane"),
            Line::from(" - [right] key : Focus history pane"),
            Line::from(" - [q] key : Quit hwatch"),
            Line::from(" - [esc] key : filter reset"),
            Line::from(" - [h] key : Show and hide help window"),
            Line::from(" - [c] key : Toggle enable/disable ANSI Color"),
            Line::from(" - [n] key : Toggle enable/disable Line Number"),
            Line::from(" - [r] key : Toggle Reverse display"),
            Line::from(" - [d] key : Toggle Diff mode"),
            Line::from(" - [o] key : Toggle Output mode"),
        ];

        let help_block = Block::default()
            .title(" [help] ")
            .borders(Borders::ALL)
            .style(Style::default().bg(Color::Reset));

        let help_p = Paragraph::new(help_text).block(help_block);
        f.render_widget(help_p, area);
    }
}

fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(r);

    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(popup_layout[1])[1]
}
