    app.no_summary = matches.get_flag("no_summary");
    app.exec = matches.get_flag("exec");
    app.diff_output_only = matches.get_flag("diff_output_only");

    app.aftercommand = matches.get_one::<String>("aftercommand").cloned();
    app.logfile = matches.get_one::<String>("logfile").cloned();

    if let Some(s) = matches.get_one::<String>("shell") {
        app.shell = s.clone();
    }

    if let Some(n_str) = matches.get_one::<String>("interval") {
        if let Ok(val) = n_str.replace(',', ".").parse::<f64>() {
            app.interval = val;
        }
    }

    app.precise = matches.get_flag("precise");

    if let Some(l_str) = matches.get_one::<String>("limit") {
        if let Ok(val) = l_str.parse::<usize>() {
            app.limit = val;
        }
    }

    if let Some(t_str) = matches.get_one::<String>("tab_size") {
        if let Ok(val) = t_str.parse::<usize>() {
            app.tab_size = val;
        }
    }

    if let Some(d_str) = matches.get_one::<String>("differences") {
        if let Ok(mode) = d_str.parse::<DiffMode>() {
            app.diff_mode = mode;
        }
    }

    if let Some(o_str) = matches.get_one::<String>("output") {
        if let Ok(mode) = o_str.parse::<OutputMode>() {
            app.output_mode = mode;
        }
    }

    if let Some(keymaps) = matches.get_many::<String>("keymap") {
        for km in keymaps {
            let parts: Vec<&str> = km.split('=').collect();
            if parts.len() != 2 {
                eprintln!("Failed to parse keymap.");
                process::exit(1);
            }
            if keymap::parse_key_event(parts[0]).is_none() || keymap::parse_action(parts[1]).is_none() {
                eprintln!("Failed to parse keymap.");
                process::exit(1);
            }
        }
    }

    if let Some(cmds) = matches.get_many::<String>("command") {
        app.command = cmds.cloned().collect();
    }

    // Check Logfile if specified
    if let Some(log_path) = &app.logfile {
        if std::path::Path::new(log_path).exists() {
            let file = match File::open(log_path) {
                Ok(f) => f,
                Err(_) => {
                    eprintln!("Failed to open logfile.");
                    process::exit(1);
                }
            };
            let metadata = file.metadata();
            if let Ok(meta) = metadata {
                if meta.len() == 0 {
                    eprintln!("file \"{}\" is exists and empty.", log_path);
                    print!("Log to the same file? (Y/n) ");
                    let _ = io::stdout().flush();
                    let mut input = String::new();
                    let _ = io::stdin().read_line(&mut input);
                    let input_trim = input.trim();
                    if input_trim.eq_ignore_ascii_case("n") {
                        process::exit(1);
                    }
                } else {
                    let reader = BufReader::new(file);
                    let mut parsed_records = Vec::new();
                    let mut parse_err = None;

                    for line in reader.lines() {
                        match line {
                            Ok(line_str) => {
                                if line_str.trim().is_empty() {
                                    continue;
                                }
                                match serde_json::from_str::<HistoryRecord>(&line_str) {
                                    Ok(rec) => parsed_records.push(rec),
                                    Err(err) => {
                                        parse_err = Some(err.to_string());
                                        break;
                                    }
                                }
                            }
                            Err(_) => break,
                        }
                    }

                    if let Some(err_msg) = parse_err {
                        eprintln!("file \"{}\" is exists and json parse error.", log_path);
                        eprintln!("{}", err_msg);
                        print!("Log to the same file? (Y/n) ");
                        let _ = io::stdout().flush();
                        let mut input = String::new();
                        let _ = io::stdin().read_line(&mut input);
                        let input_trim = input.trim();
                        if input_trim.eq_ignore_ascii_case("n") {
                            process::exit(1);
                        }
                    } else {
                        app.history = parsed_records;
                        if app.command.is_empty() && !app.history.is_empty() {
                            let last_cmd = &app.history.last().unwrap().command;
                            if !last_cmd.is_empty() {
                                if let Some(parts) = shlex::split(last_cmd) {
                                    app.command = parts;
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    if app.command.is_empty() {
        eprintln!("error: command not specified and logfile is empty.\n");
        eprintln!("Usage: hwatch [OPTIONS] [command]...\n");
        eprintln!("For more information, try '--help'.");
        process::exit(2);
    }

    if app.batch {
        batch::run_batch_mode(&mut app);
    } else {
        enable_raw_mode().unwrap();
        let mut stdout = io::stdout();
        execute!(stdout, EnterAlternateScreen).unwrap();
        if app.mouse {
            execute!(stdout, EnableMouseCapture).unwrap();
        }

        let backend = CrosstermBackend::new(stdout);
        let mut terminal = Terminal::new(backend).unwrap();

        let res = view::run_tui(&mut terminal, &mut app);

        disable_raw_mode().unwrap();
        execute!(terminal.backend_mut(), LeaveAlternateScreen).unwrap();
        if app.mouse {
            execute!(terminal.backend_mut(), DisableMouseCapture).unwrap();
        }
        terminal.show_cursor().unwrap();

        if let Err(err) = res {
            println!("{:?}", err);
        }
    }
}
